-- 야민정음 7개 추가 (id 582-588) — 운영자 승인 2026-09-23 ("야민정음 모두 추가").
-- 팡주(582), 띵품(583), 쀼(584), 뚊(585), 근근웹(586), 늒네(587), 퍄(588).
-- 팡주는 지역 비하 전례가, 숲튽훈(581)은 실명 비하 리스크가 브리핑에서 보고됐고 대표가 전부 승인했다.
--
-- NOTE: filename timestamp differs from the production migration version
-- (MCP apply time becomes the version) — repo-wide convention, see CLAUDE.md.
begin;

insert into public.words (id, word, romanization, category, secondary_category, short_desc, short_desc_i18n, pronunciation, meanings, origin, origin_i18n, usage, usage_i18n, related_words, aliases, likes, saves, translations) values
('582', '팡주', 'Pang-ju', 'yaminjeongeum', null, '''광주''를 모양이 닮은 글자로 바꿔 쓴 야민정음 (중립적 애칭 아님)', '{"de": "''Gwangju'' mit einer ahnlich aussehenden Silbe - kein neutraler Spitzname", "en": "''Gwangju'' respelled with a look-alike syllable - not a neutral nickname", "es": "''Gwangju'' reescrito con una silaba parecida; no es un apodo neutral", "ja": "「光州」を形の似た字に変えた野民正音(中立的な愛称ではない)", "vi": "''Gwangju'' viet lai bang am tiet trong giong - khong phai biet danh trung tinh"}'::jsonb, '[팡주]', '[{"definition": "전라남도 광주광역시를 야민정음으로 적은 말. ''광''과 ''팡''의 모양이 닮은 점을 이용한 치환형으로, 도시 이름 전체를 바꾼 ''팡주팡역시''나 뒷부분만 바꾼 ''팡역시'' 형태로도 쓴다. 같은 규칙으로 만들어진 ''머구(대구)''와 짝처럼 언급되지만, 팡주는 온라인에서 지역 혐오 게시물과 함께 쓰인 전례가 있어 대구 쪽과 뉘앙스가 같지 않다.", "definition_i18n": {"de": "Yaminjeongeum-Schreibung von Gwangju, der Metropole im Sudwesten, mit 팡 statt des ahnlichen 광. Auch als 팡주팡역시 (ganzer Stadtname umgeschrieben) oder nur 팡역시. Meist zusammen mit 머구 (Daegu) genannt, nach derselben Regel gebildet, doch 팡주 tauchte online auch in regional hetzerischen Posts auf - der Ton ist nicht derselbe.", "en": "Yaminjeongeum spelling of Gwangju, the metropolitan city in the southwest, swapping 광 for the look-alike 팡. It also appears as 팡주팡역시 (the whole city name respelled) or just 팡역시. It is usually cited alongside 머구 (Daegu), made by the same rule, but 팡주 has a record of appearing in regionally hateful posts online, so the two do not carry the same tone.", "es": "Escritura yaminjeongeum de Gwangju, la ciudad metropolitana del suroeste, cambiando 광 por el parecido 팡. Aparece tambien como 팡주팡역시 (todo el nombre reescrito) o solo 팡역시. Suele citarse junto a 머구 (Daegu), hecho con la misma regla, pero 팡주 tiene antecedentes de uso en publicaciones de odio regional, asi que el tono no es el mismo.", "ja": "全羅南道の光州広域市を野民正音で書いた語。「광」と「팡」の形が似ていることを使った置換型で、市名全体を変えた「팡주팡역시」や後半だけの「팡역시」の形でも使う。同じ規則でできた「머구(大邱)」と対で語られるが、팡주はネット上で地域ヘイトの投稿とともに使われた前例があり、ニュアンスは同じではない。", "vi": "Cach viet yaminjeongeum cua Gwangju, thanh pho truc thuoc o tay nam, doi 광 thanh 팡 trong giong. Con xuat hien duoi dang 팡주팡역시 (viet lai ca ten) hoac chi 팡역시. Thuong duoc nhac cung 머구 (Daegu) do cung quy tac, nhung 팡주 tung xuat hien trong cac bai dang ky thi vung mien tren mang, nen sac thai khong giong nhau."}, "examples": [{"de": "Ich habe 팡주팡역시 zuerst nicht als Gwangju erkannt.", "eng": "I did not catch 팡주팡역시 as Gwangju at first.", "es": "Al principio no reconoci 팡주팡역시 como Gwangju.", "ja": "「팡주팡역시」って書いてあるの、最初は分からなかった。", "kor": "팡주팡역시라고 쓴 거 처음엔 못 알아봤어.", "vi": "Luc dau tui khong nhan ra 팡주팡역시 la Gwangju."}, {"de": "Dieses Wort hinterlaesst einen schalen Beigeschmack, wenn man es nur aus Spass nutzt.", "eng": "This one leaves a bad aftertaste to use just for laughs.", "es": "Esta palabra deja mal sabor si se usa solo por risa.", "ja": "この語は面白半分で使うには後味が悪い。", "kor": "이 단어는 재미로만 쓰기엔 뒷맛이 안 좋아.", "vi": "Tu nay dung de dua thoi thi van thay gon gon."}], "type": "명사"}]'::jsonb, '야민정음의 지명 치환 계열에서 나왔다. ''대→머'' 규칙으로 대구가 머구, 대전이 머전이 되듯 ''광→팡'' 규칙으로 광주가 팡주가 된다. 2022년 한글날을 앞두고 국립국어원이 야민정음 소개 행사에 ''팡역시''를 예시로 올렸다가 한글 파괴 논란과 지역 비하 지적을 함께 받았고, 이 논란으로 단어가 다시 알려졌다.', '{"de": "Es stammt aus dem Ortsnamen-Zweig des Yaminjeongeum: wie die Regel 대 zu 머 aus Daegu 머구 macht, macht die Regel 광 zu 팡 aus Gwangju 팡주. 2022 nutzte das Nationale Institut fur Koreanische Sprache vor dem Hangul-Tag 팡역시 als Beispiel und erntete Kritik sowohl wegen Hangul-Zerstorung als auch wegen regionaler Herabsetzung - die Debatte brachte das Wort zuruck in die Schlagzeilen.", "en": "It comes from the place-name branch of Yaminjeongeum: just as the 대-to-머 rule turns Daegu into 머구, the 광-to-팡 rule turns Gwangju into 팡주. In 2022, ahead of Hangul Day, the National Institute of Korean Language used 팡역시 as an example in a Yaminjeongeum event and drew criticism both for degrading Hangul and for regional disparagement - the controversy put the word back in the news.", "es": "Viene de la rama de toponimos del yaminjeongeum: igual que la regla 대 a 머 convierte Daegu en 머구, la regla 광 a 팡 convierte Gwangju en 팡주. En 2022, antes del Dia del Hangul, el Instituto Nacional de la Lengua Coreana uso 팡역시 como ejemplo en un acto y recibio criticas por degradar el hangul y por menosprecio regional; la polemica devolvio la palabra a los titulares.", "ja": "野民正音の地名置換系から出た語。「대→머」規則で大邱が머구になるように、「광→팡」規則で光州が팡주になる。2022年のハングルの日を前に国立国語院が野民正音紹介行事で「팡역시」を例示し、ハングル破壊論争と地域蔑視の指摘を同時に受け、この騒動で再び知られた。", "vi": "No den tu nhanh dia danh cua yaminjeongeum: giong nhu quy tac 대 thanh 머 bien Daegu thanh 머구, quy tac 광 thanh 팡 bien Gwangju thanh 팡주. Nam 2022, truoc Ngay Hangul, Vien Quoc ngu Han Quoc dung 팡역시 lam vi du trong su kien va bi chi trich vua pha hoai Hangul vua mieu thi vung mien; vu tranh cai dua tu nay tro lai tin tuc."}'::jsonb, '읽는 재미로 소개할 수는 있어도 직접 쓰기는 권하지 않는다. 특히 광주 출신 사람 앞에서 쓰면 놀리는 것으로 받아들여질 수 있다. 어느 쪽으로 검색해도 항목 하나다 — ''팡주'', ''팡주팡역시'', ''팡역시'' 모두 이 단어로 찾을 수 있다.', '{"de": "Kennen ja, benutzen lieber nicht. Vor jemandem aus Gwangju gesagt, kann es als Spott ankommen. Jede Form fuhrt zu diesem einen Eintrag - 팡주, 팡주팡역시 und 팡역시.", "en": "Fine to know, not recommended to use. Said in front of someone from Gwangju it can read as mockery. Every form lands on this one entry - 팡주, 팡주팡역시 and 팡역시 all find it.", "es": "Conviene conocerla, no usarla. Dicha ante alguien de Gwangju puede sonar a burla. Cualquier forma lleva a esta unica entrada: 팡주, 팡주팡역시 y 팡역시.", "ja": "知っておくのはよいが、自分で使うのは勧めない。特に光州出身の人の前で使うとからかいと受け取られうる。どの表記で検索しても項目は一つ — 「팡주」「팡주팡역시」「팡역시」いずれでも見つかる。", "vi": "Biet thi duoc, khong nen dung. Noi truoc mat nguoi Gwangju co the bi hieu la che gieu. Tra dang nao cung ra mot muc nay - 팡주, 팡주팡역시 va 팡역시."}'::jsonb, '{"머구광역시","머한민국","댕댕이"}'::text[], '{"팡주팡역시","팡역시"}'::text[], 0, 0, '[{"lang": "🇺🇸 EN", "text": "Gwangju (meme spelling, loaded)"}, {"lang": "🇯🇵 JA", "text": "光州(野民正音表記・含みあり)"}, {"lang": "🇨🇳 ZH", "text": "光州(谐形写法，带贬义语境)"}, {"lang": "🇻🇳 VI", "text": "Gwangju (cach viet che chu, co ham y)"}, {"lang": "🇪🇸 ES", "text": "Gwangju (grafia meme, connotada)"}, {"lang": "🇩🇪 DE", "text": "Gwangju (Meme-Schreibweise, belastet)"}]'::jsonb),
('583', '띵품', 'Tting-pum', 'yaminjeongeum', null, '''명품''을 모양이 닮은 글자로 바꿔 쓴 야민정음', '{"de": "''Luxusware'' mit einer ahnlich aussehenden Silbe geschrieben", "en": "''Luxury goods'' respelled with a look-alike syllable", "es": "''Articulo de lujo'' reescrito con una silaba parecida", "ja": "「名品」を形の似た字に変えた野民正音", "vi": "''Hang hieu'' viet lai bang am tiet trong giong"}'::jsonb, '[띵품]', '[{"definition": "''명품(名品)''을 야민정음으로 적은 말. ''명''을 모양이 닮은 ''띵''으로 바꾼 치환형이다. 실제 럭셔리 브랜드를 가리키기도 하지만, 값이 싼 물건인데 품질이 기대 이상일 때 ''이거 띵품이다''처럼 과장해 칭찬하는 쪽으로 더 자주 쓴다.", "definition_i18n": {"de": "Yaminjeongeum-Schreibung von 명품, Luxusware, mit 띵 statt des ahnlichen 명. Es kann eine echte Designermarke meinen, wird aber haufiger genutzt, um etwas Billiges zu uberloben, das mehr liefert als es kostet: 이거 띵품이다 (das ist Luxusklasse).", "en": "Yaminjeongeum spelling of 명품, luxury goods, swapping 명 for the look-alike 띵. It can point at a real designer label, but it is used more often to over-praise something cheap that punches above its price: 이거 띵품이다 (this thing is luxury-grade).", "es": "Escritura yaminjeongeum de 명품, articulos de lujo, cambiando 명 por el parecido 띵. Puede senalar una marca de verdad, pero se usa mas para elogiar en exceso algo barato que rinde por encima de su precio: 이거 띵품이다 (esto es de lujo).", "ja": "「名品(명품)」を野民正音で書いた語。「명」を形の似た「띵」に替えた置換型。実際のラグジュアリーブランドを指すこともあるが、安いのに品質が期待以上のとき「이거 띵품이다」と大げさに褒める使い方のほうが多い。", "vi": "Cach viet yaminjeongeum cua 명품, hang hieu, doi 명 thanh 띵 trong giong. No co the chi hang hieu that, nhung thuong dung de khen qua len mot mon re ma chat luong vuot mong doi: 이거 띵품이다 (mon nay dinh nhu hang hieu)."}, "examples": [{"de": "Hat drei Euro gekostet, aber die Verarbeitung ist Tting-pum.", "eng": "It cost three bucks but the finish is tting-pum.", "es": "Costo tres mil wones y el acabado es tting-pum.", "ja": "3千ウォンなのに作りがティンプムだわ。", "kor": "3천 원짜리인데 마감이 띵품이야.", "vi": "Co ba nghin won thoi ma hoan thien dung la tting-pum."}, {"de": "Diese Ohrhorer klingen wirklich nach Tting-pum.", "eng": "These cheap earbuds sound genuinely tting-pum.", "es": "Estos auriculares suenan de verdad a tting-pum.", "ja": "このワイヤレスイヤホン、マジでティンプムの音する。", "kor": "이 무선 이어폰 진짜 띵품 소리 난다.", "vi": "Cai tai nghe nay nghe dung chat tting-pum luon."}], "type": "명사"}]'::jsonb, '''명→띵'' 치환은 야민정음에서 가장 생산적인 규칙이라 명사 앞의 ''명''이 붙은 말이면 거의 다 ''띵''으로 바꿔 쓸 수 있다. 띵작(명작)·띵곡(명곡)이 먼저 자리를 잡은 뒤 같은 틀에서 띵언·띵문대·띵품이 따라 나왔다. 그래서 띵품은 따로 만들어진 유행어라기보다 규칙에서 파생된 말에 가깝다.', '{"de": "Der Tausch 명 zu 띵 ist die produktivste Regel des Yaminjeongeum, fast jedes Wort mit 명 am Anfang lasst sich so umschreiben. 띵작 (Meisterwerk) und 띵곡 (grossartiger Song) setzten sich zuerst durch, aus derselben Schablone folgten 띵언, 띵문대 und 띵품. 띵품 ist damit weniger ein eigens gepragtes Modewort als ein von der Regel erzeugtes.", "en": "The 명-to-띵 swap is the most productive rule in Yaminjeongeum, so almost any word starting with 명 can be respelled. 띵작 (masterpiece) and 띵곡 (great song) landed first, and 띵언, 띵문대 and 띵품 followed from the same template. 띵품 is therefore less a separately coined buzzword than a word generated by the rule.", "es": "El cambio de 명 a 띵 es la regla mas productiva del yaminjeongeum, asi que casi cualquier palabra que empiece por 명 puede reescribirse. 띵작 (obra maestra) y 띵곡 (cancion buenisima) se asentaron primero, y de la misma plantilla salieron 띵언, 띵문대 y 띵품. Por eso 띵품 es menos una moda acunada aparte que una palabra generada por la regla.", "ja": "「명→띵」の置換は野民正音で最も生産的な規則で、「명」で始まる語はほぼ全て置換できる。띵작(名作)・띵곡(名曲)が先に定着し、同じ型から띵언・띵문대・띵품が続いた。つまり띵품は個別に作られた流行語というより規則から派生した語に近い。", "vi": "Quy tac doi 명 thanh 띵 la quy tac nang suat nhat trong yaminjeongeum, nen gan nhu tu nao bat dau bang 명 deu viet lai duoc. 띵작 (kiet tac) va 띵곡 (bai hat hay) on dinh truoc, roi 띵언, 띵문대 va 띵품 theo cung khuon. Vi vay 띵품 khong hang mot tu moi duoc dat rieng ma la tu do quy tac sinh ra."}'::jsonb, '실제 명품 브랜드 이야기에 쓰면 비꼬는 것처럼 들릴 수 있어, 보통은 저렴한 물건을 칭찬하는 쪽으로 쓴다. 쇼핑 후기나 댓글에서 자주 보이고 격식 있는 글에는 쓰지 않는다.', '{"de": "Auf eine echte Luxusmarke angewandt kann es sarkastisch wirken, deshalb trifft es meist billige Dinge, die gelobt werden. Haufig in Shopping-Reviews und Kommentaren, nie in formellen Texten.", "en": "Using it about an actual luxury brand can come off sarcastic, so it usually lands on cheap items being praised. Common in shopping reviews and comments, never in formal writing.", "es": "Aplicarlo a una marca de lujo real puede sonar sarcastico, asi que suele recaer en cosas baratas que se elogian. Frecuente en resenas de compras y comentarios, nunca en textos formales.", "ja": "本物のブランドの話に使うと皮肉に聞こえかねないので、普通は安い物を褒めるときに使う。購入レビューやコメントでよく見かけ、堅い文章では使わない。", "vi": "Dung cho hang hieu that co the nghe nhu mia mai, nen thuong danh cho mon re duoc khen. Hay gap trong review mua sam va binh luan, khong dung trong van ban trang trong."}'::jsonb, '{"띵작","띵곡","띵언","띵문"}'::text[], null, 0, 0, '[{"lang": "🇺🇸 EN", "text": "Luxury-grade / top quality (meme spelling)"}, {"lang": "🇯🇵 JA", "text": "名品(野民正音表記)"}, {"lang": "🇨🇳 ZH", "text": "名品(谐形网络写法)"}, {"lang": "🇻🇳 VI", "text": "Hang hieu (cach viet che chu)"}, {"lang": "🇪🇸 ES", "text": "Articulo de lujo (grafia meme)"}, {"lang": "🇩🇪 DE", "text": "Luxusware (Meme-Schreibweise)"}]'::jsonb),
('584', '쀼', 'Ppyu', 'yaminjeongeum', 'love', '''부부''를 한 글자로 눌러 붙인 야민정음', '{"de": "''Ehepaar'' in eine einzige Silbe gestaucht", "en": "''Married couple'' squeezed into one syllable", "es": "''Matrimonio'' comprimido en una sola silaba", "ja": "「夫婦」を一文字に押し込んだ野民正音", "vi": "''Vo chong'' nen vao mot am tiet"}'::jsonb, '[쀼]', '[{"definition": "''부부''를 한 글자로 압축해 적은 말. 두 글자를 좌우로 붙이면 ''ㅃ + ㅠ'' 한 글자가 된다. 법적으로 결혼한 부부만이 아니라 부부처럼 붙어 다니는 커플, 예능 속 가상 부부까지 귀엽게 부를 때 쓴다. ''쀼커플''처럼 뒤에 말을 붙여 쓰기도 한다.", "definition_i18n": {"de": "부부, ein Ehepaar, in ein Zeichen gestaucht: stellt man die beiden Silben nebeneinander, ergibt sich ㅃ + ㅠ. Es gilt nicht nur fur rechtlich Verheiratete, sondern auch fur unzertrennliche Paare und die Fake-Ehepaare in Shows, stets liebevoll. Es laesst sich kombinieren, etwa 쀼커플.", "en": "부부, a married couple, compressed into one character: set the two syllables side by side and you get ㅃ + ㅠ. It is not limited to legally married people - it covers couples who are inseparable and the fake married pairs on variety shows, always affectionately. It also combines, as in 쀼커플.", "es": "부부, matrimonio, comprimido en un caracter: junta las dos silabas y sale ㅃ + ㅠ. No se limita a casados legalmente: vale para parejas inseparables y para los matrimonios ficticios de los programas, siempre con carino. Tambien se combina, como en 쀼커플.", "ja": "「부부(夫婦)」を一文字に圧縮して書いた語。二文字を左右に並べると「ㅃ+ㅠ」の一文字になる。法律上の夫婦に限らず、いつもくっついているカップルやバラエティの仮想夫婦まで可愛く呼ぶときに使う。「쀼커플」のように後ろに語を付けることもある。", "vi": "부부, vo chong, duoc nen vao mot chu: dat hai am tiet canh nhau thi ra ㅃ + ㅠ. Khong chi danh cho nguoi ket hon hop phap - no dung cho ca cap doi dinh nhau va cac cap vo chong gia trong show, luon voi y trin men. No cung ghep duoc, nhu 쀼커플."}, "examples": [{"de": "Ihr zwei seht komplett aus wie ein Ppyu.", "eng": "You two totally look like a ppyu.", "es": "Vosotros dos pareceis un ppyu total.", "ja": "二人、完全にプユみたい。", "kor": "둘이 완전 쀼 같아 보여.", "vi": "Hai dua nhin y het mot cap ppyu."}, {"de": "Die Chemie beim Ppyu war diese Woche richtig gut.", "eng": "The ppyu had great chemistry this week.", "es": "Esta semana el ppyu tuvo una quimica buenisima.", "ja": "今週のプユ、ケミ本当によかった。", "kor": "이번 주 쀼 케미 진짜 좋더라.", "vi": "Tuan nay cap ppyu hop nhau cuc ky."}], "type": "명사"}]'::jsonb, '야민정음의 압축 방식에서 나왔다. ''돌돔''을 ''뚊''으로 적는 것과 같은 원리로, 두 글자를 한 글자에 눌러 담는다. 확산 계기는 두 갈래로 이야기된다 — MBC ''우리 결혼했어요''에서 육성재와 조이 짝을 ''쀼커플''이라 부른 것, 그리고 2020년 JTBC 드라마 ''부부의 세계''를 시청자들이 ''쀼의 세계''로 줄여 부른 것이다. 둘 다 실제로 쓰인 사례다.', '{"de": "Es stammt aus der Stauchmethode des Yaminjeongeum, demselben Prinzip, das 돌돔 als 뚊 schreibt. Zur Verbreitung gibt es zwei Darstellungen: MBCs We Got Married, wo Yook Sung-jae und Joy das 쀼커플 hiessen, und das JTBC-Drama 부부의 세계 von 2020, das Zuschauer zu 쀼의 세계 kurzten. Beides ist belegt.", "en": "It comes from the compression method of Yaminjeongeum, the same principle that writes 돌돔 as 뚊. Two accounts are given for how it spread: MBC''s We Got Married, where Yook Sung-jae and Joy were called the 쀼커플, and the 2020 JTBC drama 부부의 세계 (The World of the Married), which viewers shortened to 쀼의 세계. Both are real.", "es": "Viene del metodo de compresion del yaminjeongeum, el mismo principio que escribe 돌돔 como 뚊. Se cuentan dos vias de difusion: We Got Married de MBC, donde a Yook Sung-jae y Joy se les llamo 쀼커플, y el drama de JTBC 부부의 세계 (2020), que los espectadores abreviaron como 쀼의 세계. Ambas son reales.", "ja": "野民正音の圧縮方式から出た語。「돌돔」を「뚊」と書くのと同じ原理で、二文字を一文字に押し込む。広まった経緯は二通り語られる — MBC「私たち結婚しました」でユク・ソンジェとジョイの組を「쀼커플」と呼んだこと、そして2020年のJTBCドラマ「夫婦の世界」を視聴者が「쀼의 세계」と縮めて呼んだこと。どちらも実際の用例。", "vi": "No den tu cach nen cua yaminjeongeum, cung nguyen ly viet 돌돔 thanh 뚊. Co hai loi ke ve cach no lan rong: chuong trinh We Got Married cua MBC, noi Yook Sung-jae va Joy duoc goi la 쀼커플, va bo phim JTBC 부부의 세계 nam 2020 ma khan gia rut thanh 쀼의 세계. Ca hai deu co that."}'::jsonb, '애정 어린 표현이라 놀리는 느낌은 거의 없다. 다만 당사자 앞에서 쓰면 사귀는 사이로 단정하는 셈이라 조심할 것. 예능 이야기나 팬 커뮤니티에서 가장 자주 보인다.', '{"de": "Es ist liebevoll, nicht spottisch, doch gegenuber den Betroffenen unterstellt es eine Beziehung - also vorsichtig. Am haufigsten in Gesprachen uber Shows und in Fan-Communitys.", "en": "It is affectionate rather than teasing, but said to the people involved it presumes they are a couple, so tread carefully. Most common in talk about variety shows and in fan communities.", "es": "Es carinoso mas que burlon, pero dicho a los interesados da por hecho que son pareja, asi que con cuidado. Sobre todo en charlas sobre programas y en comunidades de fans.", "ja": "愛情のこもった表現でからかう感じはほぼないが、当事者の前で使うと付き合っていると決めつけることになるので注意。バラエティの話やファンコミュニティで最もよく見る。", "vi": "No trin men chu khong phai che gieu, nhung noi truoc mat nguoi trong cuoc thi coi nhu khang dinh ho la mot cap, nen can than. Hay gap nhat khi ban ve show va trong cong dong fan."}'::jsonb, '{"뚊","댕댕이","삼귀다"}'::text[], '{"쀼커플"}'::text[], 0, 0, '[{"lang": "🇺🇸 EN", "text": "Couple / married pair (compressed spelling of 부부)"}, {"lang": "🇯🇵 JA", "text": "夫婦・カップル(부부の圧縮表記)"}, {"lang": "🇨🇳 ZH", "text": "夫妻・情侣(부부的压缩写法)"}, {"lang": "🇻🇳 VI", "text": "Vo chong, cap doi (viet nen cua 부부)"}, {"lang": "🇪🇸 ES", "text": "Pareja, matrimonio (grafia comprimida de 부부)"}, {"lang": "🇩🇪 DE", "text": "Paar, Ehepaar (gestauchte Schreibung von 부부)"}]'::jsonb),
('585', '뚊', 'Ttolm', 'yaminjeongeum', null, '''돌돔''을 한 글자로 눌러 붙인 야민정음', '{"de": "''Geissbrasse'' in eine einzige Silbe gestaucht", "en": "''Striped beakfish'' squeezed into one syllable", "es": "''Sargo picudo'' comprimido en una sola silaba", "ja": "「イシダイ」を一文字に押し込んだ野民正音", "vi": "''Ca ho chan chan'' nen vao mot am tiet"}'::jsonb, '[똠]', '[{"definition": "바닷물고기 ''돌돔''을 한 글자로 압축해 적은 말. ''돌''과 ''돔''을 위아래로 겹쳐 붙이면 ''ㄸ + ㅗ + ㄹㅁ'' 한 글자가 된다. 글자를 닮은 모양으로 바꾸거나 돌리는 다른 야민정음과 달리, 여러 글자를 하나로 눌러 담는 압축 방식의 대표 사례로 늘 함께 소개된다.", "definition_i18n": {"de": "Der Meeresfisch 돌돔 (Geissbrasse) in ein Zeichen gestaucht: legt man 돌 und 돔 ubereinander, entsteht eine Silbe, ㄸ + ㅗ + ㄹㅁ. Anders als Yaminjeongeum-Worter, die ahnliche Buchstaben tauschen oder drehen, gilt dieses stets als Paradebeispiel der Stauchmethode.", "en": "The sea fish 돌돔 (striped beakfish) compressed into one character: stack 돌 and 돔 and you get a single syllable, ㄸ + ㅗ + ㄹㅁ. Unlike the Yaminjeongeum words that swap look-alike letters or rotate them, this one is always cited as the showcase of the compression method - several syllables packed into one.", "es": "El pez marino 돌돔 (sargo picudo) comprimido en un solo caracter: al apilar 돌 y 돔 sale una silaba, ㄸ + ㅗ + ㄹㅁ. A diferencia de los yaminjeongeum que cambian letras parecidas o las giran, este se cita siempre como el ejemplo estrella del metodo de compresion.", "ja": "海の魚「イシダイ(돌돔)」を一文字に圧縮して書いた語。「돌」と「돔」を上下に重ねると「ㄸ+ㅗ+ㄹㅁ」の一文字になる。似た形に替えたり回したりする他の野民正音と違い、複数の字を一つに押し込む圧縮方式の代表例として必ず紹介される。", "vi": "Ca bien 돌돔 duoc nen vao mot chu: xep 돌 len 돔 thi thanh mot am tiet, ㄸ + ㅗ + ㄹㅁ. Khac voi cac tu yaminjeongeum doi chu trong giong hay quay chu, tu nay luon duoc dan lam vi du tieu bieu cho kieu nen nhieu am tiet vao mot."}, "examples": [{"de": "Heute einen Ttolm gefangen.", "eng": "Caught one ttolm today.", "es": "Hoy pesque un ttolm.", "ja": "今日トルムを一匹釣った。", "kor": "오늘 뚊 한 마리 낚았다.", "vi": "Hom nay cau duoc mot con ttolm."}, {"de": "Ich habe ewig gebraucht, um zu sehen, dass 뚊 돌돔 ist.", "eng": "It took me ages to work out that 뚊 is 돌돔.", "es": "Tarde un buen rato en ver que 뚊 es 돌돔.", "ja": "뚊が돌돔だと気づくのにだいぶかかった。", "kor": "뚊이 돌돔인 거 알아채는 데 한참 걸렸어.", "vi": "Mat kha lau tui moi nhan ra 뚊 la 돌돔."}], "type": "명사"}]'::jsonb, '야민정음의 방식 중 ''압축''에 해당한다. 낚시 커뮤니티에서 돌돔 이야기가 자주 오가다가 두 글자를 한 글자로 눌러 적는 말장난이 생겼고, 언론이 야민정음을 소개할 때 회전형인 롬곡옾눞과 나란히 압축형 예시로 들면서 널리 알려졌다. 같은 방식으로 ''부부''를 ''쀼''로 적기도 한다.', '{"de": "Es gehort zum Stauch-Zweig des Yaminjeongeum. Das Wortspiel entstand in Angel-Communitys, wo staendig von 돌돔 die Rede war, und wurde bekannt, als die Presse es neben dem gedrehten 롬곡옾눞 als Stauchbeispiel anfuhrte. Dieselbe Methode macht aus 부부 (Ehepaar) 쀼.", "en": "This belongs to the compression branch of Yaminjeongeum. The pun grew in fishing communities where 돌돔 came up constantly, and it became widely known once the press used it as the compression example alongside the rotated 롬곡옾눞. The same method turns 부부 (married couple) into 쀼.", "es": "Pertenece a la rama de compresion del yaminjeongeum. El juego nacio en comunidades de pesca donde 돌돔 salia sin parar, y se hizo conocido cuando la prensa lo uso como ejemplo de compresion junto al rotado 롬곡옾눞. El mismo metodo convierte 부부 (matrimonio) en 쀼.", "ja": "野民正音の方式のうち「圧縮」に当たる。釣りコミュニティで돌돔の話が頻繁に出る中、二文字を一文字に押し込む言葉遊びが生まれ、メディアが野民正音を紹介する際に回転型の롬곡옾눞と並べて圧縮の例に挙げたことで広く知られた。同じ方式で「부부(夫婦)」を「쀼」と書くこともある。", "vi": "No thuoc nhanh nen cua yaminjeongeum. Tro choi chu nay lon len trong cac cong dong cau ca noi 돌돔 duoc nhac lien tuc, va tro nen noi tieng khi bao chi dung no lam vi du kieu nen ben canh 롬곡옾눞 kieu quay. Cung cach do bien 부부 (vo chong) thanh 쀼."}'::jsonb, '키보드로 바로 못 치는 글자라 낚시·유머 게시판에서 눈으로 보는 재미로 쓴다. 소리 내어 읽기보다 그냥 ''돌돔''이라 읽는 경우가 많다. 일상 대화에서는 거의 안 쓴다.', '{"de": "Man tippt es nicht einfach so, deshalb lebt es in Angel- und Humorforen als etwas zum Anschauen statt zum Aussprechen; die meisten lesen es laut als 돌돔. Im Alltag praktisch nie.", "en": "You cannot type it straight off a keyboard, so it lives on fishing and humour boards as something to look at rather than say; most people just read it aloud as 돌돔. Almost never in everyday speech.", "es": "No se teclea de corrido, asi que vive en foros de pesca y humor como algo para mirar mas que para decir; casi todos lo leen en voz alta como 돌돔. Practicamente nunca en habla cotidiana.", "ja": "キーボードで直接打てない字なので、釣りやユーモア掲示板で目で見る面白さとして使う。声に出すより「돌돔」と読むことが多い。日常会話ではほぼ使わない。", "vi": "Khong go thang tu ban phim duoc, nen no song tren cac box cau ca va hai huoc nhu thu de nhin hon la de noi; da so cu doc thanh 돌돔. Gan nhu khong dung trong noi chuyen hang ngay."}'::jsonb, '{"쀼","롬곡","댕댕이"}'::text[], null, 0, 0, '[{"lang": "🇺🇸 EN", "text": "Striped beakfish (compressed spelling of 돌돔)"}, {"lang": "🇯🇵 JA", "text": "イシダイ(돌돔の圧縮表記)"}, {"lang": "🇨🇳 ZH", "text": "条石鲷(돌돔的压缩写法)"}, {"lang": "🇻🇳 VI", "text": "Ca ho chan chan (viet nen cua 돌돔)"}, {"lang": "🇪🇸 ES", "text": "Sargo picudo (grafia comprimida de 돌돔)"}, {"lang": "🇩🇪 DE", "text": "Geissbrasse (gestauchte Schreibung von 돌돔)"}]'::jsonb),
('586', '근근웹', 'Geun-geun-wep', 'yaminjeongeum', null, '''루리웹''을 초성으로 줄였다가 다시 닮은 글자로 바꾼 야민정음', '{"de": "''Ruliweb'' auf Initialen gekurzt und dann mit ahnlichen Zeichen geschrieben", "en": "''Ruliweb'' shortened to initials, then respelled with look-alike letters", "es": "''Ruliweb'' reducido a iniciales y luego reescrito con letras parecidas", "ja": "「ルリウェブ」を頭子音に縮め、さらに似た字に変えた野民正音", "vi": "''Ruliweb'' rut thanh phu am dau roi viet lai bang chu trong giong"}'::jsonb, '[근근웹]', '[{"definition": "한국의 대형 인터넷 커뮤니티 ''루리웹''을 야민정음으로 적은 말. 먼저 초성만 따 ''ㄹㄹ웹''으로 줄이고, 그 ''ㄹㄹ''이 ''근근''과 모양이 닮았다는 점을 이용해 한 번 더 바꾼 두 단계 변형이다. 게임 정보와 짤로 유명한 사이트라 출처를 밝힐 때 이 이름으로 부르는 경우가 많다.", "definition_i18n": {"de": "Yaminjeongeum-Name fur Ruliweb, eine der grossen koreanischen Internet-Communitys. Zuerst wurde der Name auf die Anfangskonsonanten ㄹㄹ웹 gekurzt, dann wurden diese ㄹㄹ als ahnlich aussehendes 근근 geschrieben - eine zweistufige Umformung. Da die Seite fur Gaming-News und Memes bekannt ist, wird sie bei Quellenangaben oft so genannt.", "en": "Yaminjeongeum name for Ruliweb, one of Korea''s big internet communities. First the name was cut to its initial consonants, ㄹㄹ웹, then those ㄹㄹ were respelled as the look-alike 근근 - a two-step transformation. Since the site is known for game news and memes, people often credit a source with this name.", "es": "Nombre yaminjeongeum de Ruliweb, una de las grandes comunidades de internet coreanas. Primero se redujo a sus consonantes iniciales, ㄹㄹ웹, y luego esas ㄹㄹ se reescribieron como el parecido 근근: una transformacion en dos pasos. Como el sitio destaca por noticias de videojuegos y memes, se suele citar la fuente con este nombre.", "ja": "韓国の大型ネットコミュニティ「ルリウェブ」を野民正音で書いた語。まず頭子音だけ取って「ㄹㄹ웹」と縮め、その「ㄹㄹ」が「근근」と形が似ていることを使ってもう一度変えた二段階の変形。ゲーム情報とネタ画像で有名なサイトなので、出典を示すときにこの名で呼ぶことが多い。", "vi": "Ten yaminjeongeum cua Ruliweb, mot trong nhung cong dong mang lon cua Han Quoc. Dau tien ten bi rut con phu am dau, ㄹㄹ웹, roi ㄹㄹ ay duoc viet lai thanh 근근 trong giong - bien doi hai buoc. Vi trang nay noi tieng ve tin game va anh che, nguoi ta hay dan nguon bang ten nay."}, "examples": [{"de": "Wo hast du das Meme gesehen? - Geun-geun-wep.", "eng": "Where did you see that meme? - Geun-geun-wep.", "es": "Donde viste ese meme? - Geun-geun-wep.", "ja": "そのネタ画像どこで見た? - グングンウェプ。", "kor": "그 짤 어디서 봤어? - 근근웹.", "vi": "Anh che do thay o dau? - Geun-geun-wep."}, {"de": "Die Spieleforen auf Geun-geun-wep haben richtig gut sortierte Guides.", "eng": "The game boards on Geun-geun-wep have seriously well-organised guides.", "es": "Los foros de juegos de Geun-geun-wep tienen guias muy bien ordenadas.", "ja": "グングンウェプのゲーム板、攻略がめちゃくちゃよくまとまってる。", "kor": "근근웹 게임 게시판은 공략이 진짜 잘 정리돼 있어.", "vi": "Box game cua Geun-geun-wep co huong dan sap xep cuc ky gon."}], "type": "명사"}]'::jsonb, '초성 줄임말과 야민정음이 겹친 드문 예다. 시작은 디시인사이드 쪽에서 루리웹을 ''ㄹㄹ웹''으로 낮춰 부르던 습관이라는 설명이 있고, 한편으로 루리웹 이용자들이 자기 사이트를 부를 때도 쓴다는 설명이 있어 처음 쓴 쪽은 확정되지 않았다. 어느 쪽이든 ''ㄹ''과 ''근''의 모양 유사성이 핵심이다.', '{"de": "Ein seltener Fall, in dem Initialkurzung und Yaminjeongeum zusammenfallen. Eine Darstellung fuhrt es auf DCInside-Nutzer zuruck, die Ruliweb abwertend ㄹㄹ웹 nannten; eine andere sagt, Ruliweb-Mitglieder nutzen es fur die eigene Seite - wer es pragte, ist offen. So oder so liegt der Witz in der Ahnlichkeit von ㄹ und 근.", "en": "A rare case where an initial-consonant abbreviation and Yaminjeongeum stack. One account traces it to DCInside users belittling Ruliweb as ㄹㄹ웹; another says Ruliweb members use it for their own site, so who coined it is unsettled. Either way the point is that ㄹ and 근 look alike.", "es": "Un caso raro donde se superponen la abreviatura por consonantes iniciales y el yaminjeongeum. Una version lo atribuye a usuarios de DCInside que menospreciaban Ruliweb como ㄹㄹ웹; otra dice que los propios miembros de Ruliweb lo usan para su sitio, asi que no esta claro quien lo acuno. En cualquier caso, la clave es el parecido entre ㄹ y 근.", "ja": "頭子音の略語と野民正音が重なった珍しい例。始まりはDCインサイド側がルリウェブを「ㄹㄹ웹」と見下して呼んだ習慣だという説明と、ルリウェブ利用者が自サイトを呼ぶときにも使うという説明があり、先に使った側は確定していない。いずれにせよ「ㄹ」と「근」の形の類似が核心。", "vi": "Mot truong hop hiem khi viet tat phu am dau chong len yaminjeongeum. Mot giai thich cho rang no bat dau tu nguoi dung DCInside goi xach me Ruliweb la ㄹㄹ웹; giai thich khac noi chinh thanh vien Ruliweb dung cho trang minh, nen ai dat ra truoc van chua ro. Du sao diem mau chot la ㄹ va 근 trong giong nhau."}'::jsonb, '그 사이트를 아는 사람끼리만 통한다. 출처를 밝히거나 커뮤니티를 비교하는 대화에서 나온다. 어느 쪽으로 적어도 같은 곳을 가리킨다 — ''ㄹㄹ웹''도 같은 말이다.', '{"de": "Funktioniert nur unter Leuten, die die Seite kennen, und taucht bei Quellenangaben oder Community-Vergleichen auf. Beide Schreibungen meinen dasselbe - ㄹㄹ웹 ist dasselbe Wort.", "en": "It only works among people who know the site, and shows up when citing a source or comparing communities. Both spellings point at the same place - ㄹㄹ웹 is the same word.", "es": "Solo funciona entre quienes conocen el sitio y aparece al citar una fuente o comparar comunidades. Ambas grafias senalan lo mismo: ㄹㄹ웹 es la misma palabra.", "ja": "そのサイトを知っている人同士でしか通じない。出典を示すときやコミュニティを比べる会話で出る。どちらの表記も同じ場所を指す — 「ㄹㄹ웹」も同じ語。", "vi": "Chi nhung nguoi biet trang do moi hieu, va xuat hien khi dan nguon hay so sanh cac cong dong. Ca hai cach viet deu chi mot noi - ㄹㄹ웹 cung la tu nay."}'::jsonb, '{"늒네","댕댕이"}'::text[], '{"ㄹㄹ웹"}'::text[], 0, 0, '[{"lang": "🇺🇸 EN", "text": "Ruliweb (meme spelling of the community)"}, {"lang": "🇯🇵 JA", "text": "ルリウェブ(野民正音表記)"}, {"lang": "🇨🇳 ZH", "text": "Ruliweb论坛(谐形写法)"}, {"lang": "🇻🇳 VI", "text": "Ruliweb (cach viet che chu)"}, {"lang": "🇪🇸 ES", "text": "Ruliweb (grafia meme del foro)"}, {"lang": "🇩🇪 DE", "text": "Ruliweb (Meme-Schreibweise des Forums)"}]'::jsonb),
('587', '늒네', 'Neuk-ne', 'yaminjeongeum', null, '''뉴비''를 모양이 닮은 글자로 바꿔 쓴 야민정음', '{"de": "''Neuling'' mit ahnlich aussehenden Silben geschrieben", "en": "''Newbie'' respelled with look-alike syllables", "es": "''Novato'' reescrito con silabas parecidas", "ja": "「ニュービー」を形の似た字に変えた野民正音", "vi": "''Nguoi moi'' viet lai bang am tiet trong giong"}'::jsonb, '[능네]', '[{"definition": "영어 newbie에서 온 ''뉴비''를 야민정음으로 적은 말. ''뉴''가 ''늒''처럼, ''비''가 ''네''처럼 보인다는 점을 이용한 치환형이다. 게임이나 커뮤니티에 갓 들어온 사람을 가리키는데, 원말인 뉴비가 중립적으로도 쓰이는 데 비해 늒네는 초보를 깔보는 쪽으로 기울어 있다. 자기를 낮춰 ''저 늒네예요''처럼 쓰기도 한다.", "definition_i18n": {"de": "Yaminjeongeum-Schreibung von 뉴비, vom englischen newbie: 뉴 sieht aus wie 늒, 비 wie 네. Gemeint ist jemand, der neu in einem Spiel oder Forum ist. Wahrend 뉴비 neutral sein kann, neigt 늒네 dazu, auf Anfanger herabzusehen - auch wenn man es uber sich selbst sagt: 저 늒네예요 (ich bin Neuling).", "en": "Yaminjeongeum spelling of 뉴비, from English newbie: 뉴 looks like 늒 and 비 looks like 네. It means someone who just joined a game or community. Where plain 뉴비 can be neutral, 늒네 leans toward looking down on beginners - though people also use it about themselves, as in 저 늒네예요 (I am a newbie).", "es": "Escritura yaminjeongeum de 뉴비, del ingles newbie: 뉴 parece 늒 y 비 parece 네. Designa a quien acaba de entrar en un juego o comunidad. Mientras 뉴비 puede ser neutral, 늒네 tiende a mirar por encima del hombro al principiante, aunque tambien se usa sobre uno mismo: 저 늒네예요 (soy novato).", "ja": "英語のnewbieから来た「뉴비」を野民正音で書いた語。「뉴」が「늒」、「비」が「네」に見えることを使った置換型。ゲームやコミュニティに入りたての人を指すが、元の뉴비が中立的にも使えるのに対し늒네は初心者を見下す方に傾く。「저 늒네예요(私は初心者です)」のように自分を下げて使うこともある。", "vi": "Cach viet yaminjeongeum cua 뉴비, tu newbie tieng Anh: 뉴 trong giong 늒 va 비 trong giong 네. No chi nguoi vua vao game hay cong dong. Trong khi 뉴비 co the trung tinh, 늒네 nghieng ve coi thuong nguoi moi, du nguoi ta cung tu nhan: 저 늒네예요 (toi la linh moi)."}, "examples": [{"de": "Kannst du es einfach erklaren, statt mich Neuk-ne zu nennen?", "eng": "Could you just explain it instead of calling me a neuk-ne?", "es": "En vez de llamarme neuk-ne, me lo explicas y ya?", "ja": "ヌクネって馬鹿にしないで普通に教えてくれない?", "kor": "늒네라고 놀리지 말고 그냥 알려주면 안 됨?", "vi": "Dung che tui la neuk-ne nua, chi giup mot cai duoc khong?"}, {"de": "Ich bin Neuk-ne in dem Spiel - womit fange ich an?", "eng": "I am a neuk-ne at this game - what should I do first?", "es": "Soy neuk-ne en este juego, por donde empiezo?", "ja": "このゲーム、私ヌクネです。何からやればいい?", "kor": "저 이 겜 늒네예요, 뭐부터 해야 돼요?", "vi": "Tui la neuk-ne game nay, nen lam gi truoc?"}], "type": "명사"}]'::jsonb, '야민정음의 자모 치환형이다. 외래어를 한글로 적은 ''뉴비''를 다시 모양이 닮은 글자로 비틀었다는 점에서, 순우리말·한자어를 바꾼 댕댕이나 띵작과는 한 단계 더 꼬인 형태다. 디시인사이드나 루리웹 같은 커뮤니티에서 고정 이용자들이 신규 이용자를 부를 때 퍼졌다.', '{"de": "Ein Buchstabentausch-Typ des Yaminjeongeum. Weil es 뉴비 verdreht - selbst schon ein ins Hangul ubertragenes Lehnwort - ist es eine Stufe verschachtelter als 댕댕이 oder 띵작, die einheimische oder sinokoreanische Worter umformen. Verbreitet in Foren wie DCInside und Ruliweb, wo Stammnutzer Neuankommlinge so nannten.", "en": "A letter-swap type of Yaminjeongeum. Because it twists 뉴비 - itself a loanword already transcribed into Hangul - it is one step more convoluted than 댕댕이 or 띵작, which rework native or Sino-Korean words. It spread in communities like DCInside and Ruliweb, where regulars used it for new arrivals.", "es": "Un tipo de sustitucion de letras del yaminjeongeum. Al retorcer 뉴비, que ya es un prestamo transcrito al hangul, resulta un paso mas enrevesado que 댕댕이 o 띵작, que reelaboran palabras nativas o sinocoreanas. Se extendio en comunidades como DCInside y Ruliweb, donde los veteranos lo usaban para los recien llegados.", "ja": "野民正音の字母置換型。すでにハングル表記された外来語「뉴비」をさらにひねっている点で、固有語・漢字語を変えた댕댕이や띵작より一段こじれた形。DCインサイドやルリウェブなどのコミュニティで常連が新規利用者を呼ぶ語として広まった。", "vi": "Mot kieu doi chu cai cua yaminjeongeum. Vi no beo 뉴비 - von da la tu muon phien am sang Hangul - nen roi ram hon mot buoc so voi 댕댕이 hay 띵작 von che bien tu thuan Han. No lan trong cac cong dong nhu DCInside va Ruliweb, noi thanh vien ky cuu goi nguoi moi nhu vay."}'::jsonb, '쓰는 사람이 윗사람 위치를 잡는 말이라, 남에게 붙이면 시비로 번지기 쉽다. 자기를 가리킬 때는 안전하다. 게임 채팅·커뮤니티 댓글 밖에서는 거의 안 쓴다.', '{"de": "Es stellt die sprechende Person uber die angesprochene, gegen andere gerichtet gibt es leicht Streit; uber sich selbst ist es harmlos. Ausserhalb von Spielchats und Forenkommentaren selten.", "en": "It puts the speaker above the person addressed, so aiming it at someone else easily starts a fight; using it about yourself is safe. Rare outside game chat and community comments.", "es": "Coloca al hablante por encima del interlocutor, asi que dirigirlo a otro provoca peleas con facilidad; sobre uno mismo es seguro. Raro fuera del chat de juegos y los comentarios de foros.", "ja": "使う側が上の立場に立つ語なので、他人に向けると揉めやすい。自分を指すときは安全。ゲームチャットやコミュニティのコメント以外ではほぼ使わない。", "vi": "No dat nguoi noi o the tren, nen nham vao nguoi khac rat de gay go; tu noi ve minh thi an toan. Hiem gap ngoai chat game va binh luan cong dong."}'::jsonb, '{"근근웹","댕댕이","커엽다"}'::text[], null, 0, 0, '[{"lang": "🇺🇸 EN", "text": "Newbie / noob (meme spelling)"}, {"lang": "🇯🇵 JA", "text": "初心者・ニュービー(野民正音表記)"}, {"lang": "🇨🇳 ZH", "text": "新手(谐形网络写法)"}, {"lang": "🇻🇳 VI", "text": "Lính moi (cach viet che chu)"}, {"lang": "🇪🇸 ES", "text": "Novato (grafia meme)"}, {"lang": "🇩🇪 DE", "text": "Neuling (Meme-Schreibweise)"}]'::jsonb),
('588', '퍄', 'Pya', 'yaminjeongeum', 'exclamation', '''ㅗㅜㅑ''를 한 글자로 합친 감탄사', '{"de": "Ein Ausruf, der ㅗㅜㅑ zu einem Zeichen verschmilzt", "en": "An interjection made by fusing ㅗㅜㅑ into one character", "es": "Interjeccion que funde ㅗㅜㅑ en un solo caracter", "ja": "「ㅗㅜㅑ」を一文字に合わせた感嘆詞", "vi": "Than tu gop ㅗㅜㅑ thanh mot chu"}'::jsonb, '[퍄]', '[{"definition": "모음 세 개를 늘어놓은 감탄사 ''ㅗㅜㅑ''를 한 글자로 합쳐 적은 말. 사람의 외모나 몸매, 드물게는 대단한 결과물을 보고 숨을 들이켜듯 감탄할 때 쓴다. ''퍄퍄'', ''퍄퍄퍄''처럼 반복해 쓰기 좋고, 원말인 ''ㅗㅜㅑ''보다 느물거리는 느낌은 덜하다는 설명이 많다.", "definition_i18n": {"de": "Der Dreivokal-Ausruf ㅗㅜㅑ zu einem Zeichen verschmolzen. Es ist das Luftholen angesichts des Aussehens oder der Figur einer Person, gelegentlich auch vor einem beeindruckenden Werk. Es laesst sich gut wiederholen als 퍄퍄 oder 퍄퍄퍄 und gilt meist als weniger luestern als das urspruengliche ㅗㅜㅑ.", "en": "The three-vowel interjection ㅗㅜㅑ fused into one character. It is the sound of catching your breath at someone''s looks or figure, and occasionally at a stunning piece of work. It repeats well as 퍄퍄 or 퍄퍄퍄, and is usually described as less leering than the original ㅗㅜㅑ.", "es": "La interjeccion de tres vocales ㅗㅜㅑ fundida en un caracter. Es el sonido de quedarse sin aire ante el aspecto o la figura de alguien, y a veces ante un trabajo impresionante. Se repite bien como 퍄퍄 o 퍄퍄퍄 y suele describirse como menos lascivo que el original ㅗㅜㅑ.", "ja": "母音三つを並べた感嘆詞「ㅗㅜㅑ」を一文字に合わせた語。人の外見やスタイル、まれにすごい出来のものを見て息をのむように感嘆するときに使う。「퍄퍄」「퍄퍄퍄」と繰り返しやすく、元の「ㅗㅜㅑ」ほど嫌らしい感じはしないと説明されることが多い。", "vi": "Than tu ba nguyen am ㅗㅜㅑ gop thanh mot chu. Do la tieng hit vao khi choang truoc ngoai hinh hay voc dang ai do, doi khi truoc mot tac pham xuat sac. No lap lai de thanh 퍄퍄 hay 퍄퍄퍄, va thuong duoc mo ta la it de deu hon ban goc ㅗㅜㅑ."}, "examples": [{"de": "Hast du die neuen Konzeptfotos gesehen? Pya ...", "eng": "Have you seen the new album concept photos? Pya...", "es": "Has visto las fotos concepto del nuevo album? Pya...", "ja": "新アルバムのコンセプト写真見た? ピャ…", "kor": "새 앨범 콘셉트 사진 봤어? 퍄...", "vi": "Xem anh concept album moi chua? Pya..."}, {"de": "Die Buhnenoutfits entlocken einem echt ein Pya-pya-pya.", "eng": "Those stage outfits genuinely pull a pya-pya-pya out of you.", "es": "Esos trajes de escenario te sacan un pya-pya-pya de verdad.", "ja": "ステージ衣装、マジでピャピャピャって声出る。", "kor": "무대 의상 퍄퍄퍄 소리 나온다 진짜.", "vi": "Do dien san khau lam tui thot len pya-pya-pya that su."}], "type": "감탄사"}]'::jsonb, '원래는 감탄사 ''오우야''에서 모음만 떼어 ''ㅗㅜㅑ''로 적던 것이 시작이라는 설명이 널리 퍼져 있으나, 최초 출처는 확정되지 않았다. 여기에 야민정음 유행이 겹치면서 세 모음을 한 글자로 눌러 붙인 ''퍄''가 생겼다. 디시인사이드 등 커뮤니티에서 퍼져 SNS로 넘어왔고, 2023년에는 언론이 커여워·띵곡과 함께 SNS를 장악한 야민정음의 예로 다뤘다.', '{"de": "Verbreitet ist die Darstellung, es habe mit dem Ausruf 오우야 begonnen, nur mit seinen Vokalen als ㅗㅜㅑ geschrieben, doch der Erstbeleg ist offen. Die Yaminjeongeum-Welle stauchte die drei Vokale dann zum Zeichen 퍄. Es wanderte aus Foren wie DCInside in die sozialen Medien, und 2023 fuhrte die Presse es neben 커여워 und 띵곡 als Yaminjeongeum, das SNS erobert hat.", "en": "The common account is that it began with the interjection 오우야, written with only its vowels as ㅗㅜㅑ, though the first use is not pinned down. The Yaminjeongeum craze then compressed those three vowels into the single character 퍄. It spread from communities such as DCInside onto social media, and by 2023 the press was listing it alongside 커여워 and 띵곡 as Yaminjeongeum that had taken over SNS.", "es": "La version habitual es que empezo con la interjeccion 오우야, escrita solo con sus vocales como ㅗㅜㅑ, aunque el primer uso no esta fijado. Luego la moda del yaminjeongeum comprimio esas tres vocales en el caracter 퍄. Se extendio desde comunidades como DCInside a las redes, y en 2023 la prensa lo listaba junto a 커여워 y 띵곡 como yaminjeongeum que dominaba las redes.", "ja": "元は感嘆詞「오우야」から母音だけ取って「ㅗㅜㅑ」と書いたのが始まりという説明が広く出回っているが、初出は確定していない。そこへ野民正音の流行が重なり、三つの母音を一文字に押し込んだ「퍄」ができた。DCインサイドなどのコミュニティから広がってSNSへ移り、2023年には커여워・띵곡と並ぶSNS席巻の例として報道された。", "vi": "Cach giai thich pho bien la no bat dau tu than tu 오우야, chi viet nguyen am thanh ㅗㅜㅑ, du lan dung dau tien chua duoc xac dinh. Roi con sot yaminjeongeum nen ba nguyen am ay thanh mot chu 퍄. No lan tu cac cong dong nhu DCInside sang mang xa hoi, va den 2023 bao chi liet ke no cung 커여워 va 띵곡 nhu yaminjeongeum thong tri SNS."}'::jsonb, '사람 외모를 두고 쓰면 훑어보는 느낌이 들 수 있어, 모르는 사람이나 직장에서는 쓰지 않는 게 낫다. 음식·풍경·작품처럼 사람이 아닌 대상에 쓰면 안전하다. 어느 쪽으로 적어도 같은 말이다 — ''ㅗㅜㅑ'', ''퍄퍄'', ''퍄퍄퍄'' 모두 이 항목이다.', '{"de": "Auf das Aussehen einer Person gemunzt kann es anzuglich wirken - bei Fremden und im Buro besser lassen; bei Essen, Landschaft oder Kunst ist es harmlos. Jede Form fuhrt hierher: ㅗㅜㅑ, 퍄퍄 und 퍄퍄퍄.", "en": "Aimed at a person''s appearance it can read as ogling, so keep it away from strangers and the workplace; on food, scenery or artwork it is safe. Every form is this one entry - ㅗㅜㅑ, 퍄퍄 and 퍄퍄퍄 all land here.", "es": "Dirigido al aspecto de alguien puede sonar a repaso lascivo, asi que mejor no con desconocidos ni en el trabajo; sobre comida, paisajes u obras es seguro. Todas las formas son esta entrada: ㅗㅜㅑ, 퍄퍄 y 퍄퍄퍄.", "ja": "人の外見に向けると舐め回すように見える恐れがあるので、知らない人や職場では避けたほうがよい。食べ物や風景、作品など人以外に使えば安全。どの表記も同じ語 — 「ㅗㅜㅑ」「퍄퍄」「퍄퍄퍄」すべてこの項目。", "vi": "Nham vao ngoai hinh nguoi khac co the nghe nhu nhin cham cham, nen tranh voi nguoi la va o cong so; dung cho do an, phong canh hay tac pham thi an toan. Moi dang deu la muc nay - ㅗㅜㅑ, 퍄퍄 va 퍄퍄퍄."}'::jsonb, '{"커엽다","띵곡","헐"}'::text[], '{"ㅗㅜㅑ","퍄퍄","퍄퍄퍄"}'::text[], 0, 0, '[{"lang": "🇺🇸 EN", "text": "Whoa / phwoar (gasp of admiration)"}, {"lang": "🇯🇵 JA", "text": "うわ〜(見とれる感嘆詞)"}, {"lang": "🇨🇳 ZH", "text": "哇哦(惊艳的感叹)"}, {"lang": "🇻🇳 VI", "text": "Oa (tieng thot len vi me)"}, {"lang": "🇪🇸 ES", "text": "Uff (exclamacion de admiracion)"}, {"lang": "🇩🇪 DE", "text": "Wow (bewundernder Ausruf)"}]'::jsonb);

commit;
